export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

export interface MovieWithScreenings extends Movie {
  screenings: Screening[];
}

export interface ReservationCustomer {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
}

export interface ReservationPayload {
  screeningId: number;
  seats: string[];
  customer: ReservationCustomer;
  totalPrice: number;
}

export interface Reservation extends ReservationPayload {
  id: number;
}

export interface BookingFormValues {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  terms: boolean;
}

export interface Booking {
  screeningId: number;
  seats: string[];
  form: BookingFormValues;
  paid: boolean;
  customerEmail: string | null;
}

export function emptyFormValues(): BookingFormValues {
  return { firstName: '', lastName: '', email: '', confirmEmail: '', phone: '', terms: false };
}

function pad2(n: number): string {
  return String(n).padStart(2, '0');
}

export function dateToIso(date: Date): string {
  return `${date.getFullYear()}-${pad2(date.getMonth() + 1)}-${pad2(date.getDate())}`;
}

export function isoToDate(iso: string): Date {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y, m - 1, d);
}

export function todayIso(): string {
  return dateToIso(new Date());
}

export function addDays(iso: string, days: number): string {
  const date = isoToDate(iso);
  date.setDate(date.getDate() + days);
  return dateToIso(date);
}

export function isValidIsoDate(value: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return false;
  }
  const [y, m, d] = value.split('-').map(Number);
  const date = new Date(y, m - 1, d);
  return date.getFullYear() === y && date.getMonth() === m - 1 && date.getDate() === d;
}

export function resolveSelectedDate(dateParam: string | null): string {
  const today = todayIso();
  if (!dateParam || !isValidIsoDate(dateParam) || dateParam < today) {
    return today;
  }
  return dateParam;
}

export function weekdayFull(iso: string): string {
  return isoToDate(iso).toLocaleDateString('en-US', { weekday: 'long' });
}

export function monthShort(iso: string): string {
  return isoToDate(iso).toLocaleDateString('en-US', { month: 'short' });
}

export interface DayOption {
  date: string;
  label: string;
}

export function buildDayOptions(todayDate: string): DayOption[] {
  const options: DayOption[] = [];
  for (let i = 0; i <= 4; i++) {
    const date = addDays(todayDate, i);
    options.push({ date, label: i === 0 ? 'Today' : weekdayFull(date) });
  }
  return options;
}

export function formatShowDate(iso: string, time: string): string {
  const day = isoToDate(iso).getDate();
  return `${weekdayFull(iso)} ${day} ${monthShort(iso)} ${time}`;
}

export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function isAccessible(row: number, column: number): boolean {
  return row === 1 && column >= 10 && column <= 15;
}

export function isCouchRow(row: number): boolean {
  return row === 15;
}

export function priceForRow(row: number): number {
  if (row <= 5) {
    return 25;
  }
  if (row <= 10) {
    return 32;
  }
  if (row <= 14) {
    return 39;
  }
  return 89;
}

export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

export type RowSlot =
  | { kind: 'empty'; columns: number }
  | { kind: 'aisle' }
  | { kind: 'seat'; column: number }
  | { kind: 'couch'; columnStart: number; columnEnd: number };

export function getRowSlots(row: number): RowSlot[] {
  const slots: RowSlot[] = [];
  if (isCouchRow(row)) {
    for (let c = 1; c <= 4; c += 2) {
      slots.push({ kind: 'couch', columnStart: c, columnEnd: c + 1 });
    }
    slots.push({ kind: 'aisle' });
    for (let c = 5; c <= 20; c += 2) {
      slots.push({ kind: 'couch', columnStart: c, columnEnd: c + 1 });
    }
    slots.push({ kind: 'aisle' });
    for (let c = 21; c <= 24; c += 2) {
      slots.push({ kind: 'couch', columnStart: c, columnEnd: c + 1 });
    }
    return slots;
  }

  if (row <= 10) {
    slots.push({ kind: 'empty', columns: 4 });
  } else {
    for (let c = 1; c <= 4; c++) {
      slots.push({ kind: 'seat', column: c });
    }
  }
  slots.push({ kind: 'aisle' });
  for (let c = 5; c <= 20; c++) {
    slots.push({ kind: 'seat', column: c });
  }
  slots.push({ kind: 'aisle' });
  for (let c = 21; c <= 24; c++) {
    slots.push({ kind: 'seat', column: c });
  }
  return slots;
}

export interface ParsedSeatId {
  row: number;
  column: number;
}

export function parseSeatId(id: string): ParsedSeatId {
  const match = /^R(\d+)C(\d+)$/.exec(id);
  if (!match) {
    throw new Error(`Invalid seat id: ${id}`);
  }
  return { row: Number(match[1]), column: Number(match[2]) };
}

export interface SelectedRowGroup {
  row: number;
  label: string;
}

export function groupSelectedByRow(seats: string[]): SelectedRowGroup[] {
  const byRow = new Map<number, number[]>();
  for (const id of seats) {
    const { row, column } = parseSeatId(id);
    const columns = byRow.get(row) ?? [];
    columns.push(column);
    byRow.set(row, columns);
  }
  const rows = [...byRow.keys()].sort((a, b) => a - b);
  return rows.map((row) => {
    const columns = (byRow.get(row) ?? []).slice().sort((a, b) => a - b);
    if (isCouchRow(row)) {
      const parts: string[] = [];
      for (let i = 0; i < columns.length; i += 2) {
        parts.push(`${columns[i]}-${columns[i + 1]}`);
      }
      return { row, label: parts.join(', ') };
    }
    return { row, label: columns.join(', ') };
  });
}

export interface SummaryItem {
  row: number;
  column: number;
  isCouch: boolean;
  columnStart: number;
  columnEnd: number;
  seatIds: string[];
  price: number;
}

export function buildSummaryItems(seats: string[]): SummaryItem[] {
  const byRow = new Map<number, number[]>();
  for (const id of seats) {
    const { row, column } = parseSeatId(id);
    const columns = byRow.get(row) ?? [];
    columns.push(column);
    byRow.set(row, columns);
  }
  const items: SummaryItem[] = [];
  const rows = [...byRow.keys()].sort((a, b) => a - b);
  for (const row of rows) {
    const columns = (byRow.get(row) ?? []).slice().sort((a, b) => a - b);
    const price = priceForRow(row);
    if (isCouchRow(row)) {
      for (let i = 0; i < columns.length; i += 2) {
        const columnStart = columns[i];
        const columnEnd = columns[i + 1];
        items.push({
          row,
          column: columnStart,
          isCouch: true,
          columnStart,
          columnEnd,
          seatIds: [seatId(row, columnStart), seatId(row, columnEnd)],
          price,
        });
      }
    } else {
      for (const column of columns) {
        items.push({
          row,
          column,
          isCouch: false,
          columnStart: column,
          columnEnd: column,
          seatIds: [seatId(row, column)],
          price,
        });
      }
    }
  }
  return items;
}

export interface LegendItem {
  state: SeatState;
  label: string;
  color: string;
}

export const LEGEND_ITEMS: LegendItem[] = [
  { state: 'available', label: 'Available', color: '#2E7D32' },
  { state: 'selected', label: 'Selected', color: '#F9A825' },
  { state: 'unavailable', label: 'Unavailable', color: '#C62828' },
  { state: 'accessible', label: 'Accessible', color: '#1565C0' },
];

import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Movie, Reservation, ReservationPayload, Screening } from './models';

const BASE_URL = 'http://localhost:3000';

@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient);

  getMovies(): Observable<Movie[]> {
    return this.http.get<Movie[]>(`${BASE_URL}/movies`);
  }

  getMovie(id: number): Observable<Movie> {
    return this.http.get<Movie>(`${BASE_URL}/movies/${id}`);
  }

  getScreeningsByDate(date: string): Observable<Screening[]> {
    return this.http.get<Screening[]>(`${BASE_URL}/screenings`, { params: { date } });
  }

  getScreening(id: number): Observable<Screening> {
    return this.http.get<Screening>(`${BASE_URL}/screenings/${id}`);
  }

  createReservation(payload: ReservationPayload): Observable<Reservation> {
    return this.http.post<Reservation>(`${BASE_URL}/reservations`, payload);
  }
}

import { Injectable, signal } from '@angular/core';
import { Booking, BookingFormValues, emptyFormValues } from './models';

const STORAGE_KEY = 'cinescope.booking';

function readStorage(): Booking | null {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    return raw ? (JSON.parse(raw) as Booking) : null;
  } catch {
    return null;
  }
}

@Injectable({ providedIn: 'root' })
export class BookingService {
  private readonly state = signal<Booking | null>(readStorage());
  readonly booking = this.state.asReadonly();

  private write(booking: Booking | null): void {
    this.state.set(booking);
    if (booking) {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
    } else {
      sessionStorage.removeItem(STORAGE_KEY);
    }
  }

  startNew(screeningId: number): Booking {
    const booking: Booking = {
      screeningId,
      seats: [],
      form: emptyFormValues(),
      paid: false,
      customerEmail: null,
    };
    this.write(booking);
    return booking;
  }

  setSeats(seats: string[]): void {
    const current = this.state();
    if (!current) {
      return;
    }
    this.write({ ...current, seats });
  }

  setForm(form: BookingFormValues): void {
    const current = this.state();
    if (!current) {
      return;
    }
    this.write({ ...current, form });
  }

  markPaid(email: string): void {
    const current = this.state();
    if (!current) {
      return;
    }
    this.write({ ...current, paid: true, customerEmail: email });
  }

  clear(): void {
    this.write(null);
  }
}

import { Component, inject } from '@angular/core';
import { MAT_SNACK_BAR_DATA } from '@angular/material/snack-bar';

export interface ToastData {
  message: string;
}

@Component({
  selector: 'app-toast',
  template: `<span data-testid="toast">{{ data.message }}</span>`,
})
export class ToastComponent {
  protected readonly data = inject<ToastData>(MAT_SNACK_BAR_DATA);
}

import { Injectable, inject } from '@angular/core';
import { MatSnackBar } from '@angular/material/snack-bar';
import { ToastComponent } from './toast.component';

@Injectable({ providedIn: 'root' })
export class ToastService {
  private readonly snackBar = inject(MatSnackBar);

  show(message: string): void {
    this.snackBar.openFromComponent(ToastComponent, {
      data: { message },
      duration: 4000,
    });
  }
}

import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { BookingService } from './booking.service';

export const activeBookingGuard: CanActivateFn = (route) => {
  const bookingService = inject(BookingService);
  const router = inject(Router);
  const id = Number(route.paramMap.get('id'));
  const booking = bookingService.booking();
  if (booking && !booking.paid && booking.screeningId === id && booking.seats.length > 0) {
    return true;
  }
  return router.parseUrl('/');
};

export const paidBookingGuard: CanActivateFn = () => {
  const bookingService = inject(BookingService);
  const router = inject(Router);
  const booking = bookingService.booking();
  return booking?.paid ? true : router.parseUrl('/');
};

