        <span data-testid="summary-item-price">{{ formatPrice(item.price) }}</span>
        <button mat-stroked-button type="button" data-testid="summary-item-remove-button" (click)="remove(item)">Remove</button>
      </div>
    }
  </div>

  <p data-testid="summary-total">Total: {{ formatPrice(total()) }}</p>

  <div class="actions">
    <button mat-stroked-button type="button" data-testid="back-button" (click)="back()">Back</button>
    <button mat-raised-button color="primary" type="button" data-testid="confirm-button" (click)="confirm()">Confirm</button>
  </div>
}

