    }
  </div>

  <div class="actions">
    <button mat-stroked-button type="button" data-testid="cancel-button" (click)="onCancel()">Cancel</button>
    <button
      mat-raised-button
      color="primary"
      type="button"
      data-testid="continue-button"
      [disabled]="selectedSeats().length === 0"
      (click)="onContinue()"
