const { chromium } = require('playwright-core');

(async () => {
  const browser = await chromium.launch({
    executablePath: '/opt/ms-playwright/chromium-1234/chrome-linux/chrome',
    args: ['--no-sandbox'],
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  page.on('pageerror', (err) => errors.push('PAGEERROR: ' + err.message));
  page.on('requestfailed', (req) => errors.push('REQFAIL: ' + req.url() + ' ' + req.failure()?.errorText));

  async function shot(name) {
    await page.screenshot({ path: `/tmp/pw-test/${name}.png`, fullPage: true });
  }

  await page.goto('http://localhost:4200/?date=2026-09-15', { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  await shot('01-movie-list');
  console.log('movie cards:', await page.locator('[data-testid=movie-card]').count());

  await page.locator('[data-testid=screening-button]').first().click();
  await page.waitForURL(/\/screenings\/\d+\/seats/);
  await page.waitForTimeout(300);
  await shot('02-seat-map');
  console.log('seat count:', await page.locator('[data-testid=seat]').count());
  console.log('couch count:', await page.locator('[data-testid=couch]').count());
  console.log('accessible count:', await page.locator('[data-testid=seat][data-state=accessible]').count());
  console.log('unavailable count:', await page.locator('[data-state=unavailable]').count());

  // select a regular available seat
  const seat = page.locator('[data-testid=seat][data-state=available]').first();
  await seat.click();
  // select a couch
  const couch = page.locator('[data-testid=couch][data-state=available]').first();
  await couch.click();
  await page.waitForTimeout(100);
  await shot('03-seat-selected');
  console.log('selected count text:', await page.locator('[data-testid=selected-seats-count]').textContent());

  await page.locator('[data-testid=continue-button]').click();
  await page.waitForURL(/\/screenings\/\d+\/summary/);
  await page.waitForTimeout(200);
  await shot('04-summary');
  console.log('summary total:', await page.locator('[data-testid=summary-total]').textContent());

  await page.locator('[data-testid=confirm-button]').click();
  await page.waitForURL(/\/screenings\/\d+\/checkout/);
  await page.waitForTimeout(200);
  await shot('05-checkout-empty');

  // Try pay with empty form to see validation
  await page.locator('[data-testid=pay-button]').click();
  await page.waitForTimeout(300);
  await shot('06-checkout-invalid');
  console.log('toast text:', await page.locator('[data-testid=toast]').textContent().catch(() => 'NO TOAST'));

  // fill form properly
  await page.locator('[data-testid=first-name-input]').fill('Anna');
  await page.locator('[data-testid=last-name-input]').fill('Kowalska');
  await page.locator('[data-testid=email-input]').fill('anna.kowalska@example.com');
  await page.locator('[data-testid=confirm-email-input]').fill('anna.kowalska@example.com');
  await page.locator('[data-testid=phone-input]').fill('123456789');
  await page.locator('[data-testid=terms-checkbox]').click();
  await page.waitForTimeout(200);
  await shot('07-checkout-filled');

  await page.locator('[data-testid=pay-button]').click();
  await page.waitForURL(/\/confirmation/, { timeout: 5000 }).catch(async () => {
    console.log('did not navigate to confirmation, current url:', page.url());
    await shot('08-pay-failed');
  });
  await page.waitForTimeout(300);
  await shot('09-confirmation');
  console.log('confirmation message:', await page.locator('[data-testid=confirmation-message]').textContent().catch(() => 'MISSING'));

  console.log('ERRORS:', JSON.stringify(errors, null, 2));
  await browser.close();
})();

