@if (movie(); as movie) {
  <h1 data-testid="summary-title">Your tickets</h1>

  <div data-testid="summary-list" class="summary-list">
    @for (item of items(); track item.seatIds.join(',')) {
      <div data-testid="summary-item" class="summary-item">
        <span data-testid="summary-item-title">{{ movie.title }}</span>
        <span data-testid="summary-item-datetime">{{ datetime() }}</span>
        <span data-testid="summary-item-row">{{ item.row }}</span>
        <span data-testid="summary-item-seat">
          {{ item.isCouch ? 'Couch ' + item.columnStart + '-' + item.columnEnd : item.column }}
        </span>
        <span data-testid="summary-item-price">{{ formatPrice(item.price) }}</span>
        <button mat-stroked-button type="button" data-testid="summary-item-remove-button" (click)="remove(item)">Remove</button>
      </div>
    }
  </div>

  <p data-testid="summary-total">Total: {{ formatPrice(total()) }}</p>

  <div class="actions">
    <button mat-stroked-button type="button" data-testid="back-button" (click)="back()">Back</button>
    <button mat-raised-button color="primary" type="button" data-testid="confirm-button" (click)="confirm()">Confirm</button>
  </div>
}

