const { chromium } = require('playwright-core');

(async () => {
  const browser = await chromium.launch({
    executablePath: '/opt/ms-playwright/chromium-1234/chrome-linux/chrome',
    args: ['--no-sandbox'],
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('console', (msg) => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  page.on('pageerror', (err) => errors.push('PAGEERROR: ' + err.message));

  const url = process.argv[2] || 'http://localhost:4200';
  await page.goto(url, { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  const outPath = process.argv[3] || '/tmp/pw-test/screenshot.png';
  await page.screenshot({ path: outPath });
  console.log('HTML snippet:', (await page.content()).slice(0, 500));
  console.log('ERRORS:', JSON.stringify(errors, null, 2));
