  await page.addInitScript(() => {
    const FIXED = new Date(2026, 8, 15, 10, 0, 0).getTime();
    const OriginalDate = Date;
    class FakeDate extends OriginalDate {
      constructor(...args) {
        if (args.length === 0) super(FIXED);
        else super(...args);
      }
      static now() { return FIXED; }
    }
    Date = FakeDate;
  });

  const BASE = 'http://[::1]:4200';
  const API = 'http://[::1]:3000';

  function log(label, val) { console.log(label + ':', val); }

  // ---- Test 1: guard redirects without a booking ----
  await page.goto(BASE + '/screenings/1/summary', { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  log('T1 summary-no-booking url', page.url());

  await page.goto(BASE + '/screenings/1/checkout', { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  log('T1 checkout-no-booking url', page.url());

  await page.goto(BASE + '/confirmation', { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  log('T1 confirmation-no-booking url', page.url());

  // ---- Test 2: normal flow to pick a screening, select seats ----
  await page.goto(BASE + '/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);

  // datepicker min-date check: open datepicker, try to find a disabled date before today
  await page.locator('[data-testid=date-picker] input, input[data-testid=date-picker]').first().click().catch(() => {});
  // try the toggle button if input click doesn't open it
  const calendarToggle = page.locator('mat-datepicker-toggle button');
  if (await calendarToggle.count()) {
    await calendarToggle.first().click();
  }
  await page.waitForTimeout(200);
  const disabledCount = await page.locator('.mat-calendar-body-disabled').count().catch(() => -1);
  log('T2 datepicker disabled-cell-count (should be >0 for past dates)', disabledCount);
  await page.keyboard.press('Escape');
  await page.waitForTimeout(100);

  const screeningHref = await page.locator('[data-testid=screening-button]').first().getAttribute('data-screening-id').catch(() => null);
  await page.locator('[data-testid=screening-button]').first().click();
  await page.waitForURL(/\/screenings\/(\d+)\/seats/);
  const screeningId = page.url().match(/screenings\/(\d+)\//)[1];
  log('T2 screeningId', screeningId);
  await page.waitForTimeout(200);

  // select 5 seats (not couches) to test cap boundary later
  const availableSeats = page.locator('[data-testid=seat][data-state=available]');
  const seatCountAvail = await availableSeats.count();
  log('T2 available seat count', seatCountAvail);

  // Select 10 single seats (cap)
  for (let i = 0; i < 10; i++) {
    await availableSeats.nth(i).click();
  }
  await page.waitForTimeout(100);
  log('T2 selected after 10 singles', await page.locator('[data-testid=selected-seats-count]').textContent());

  // try to select an 11th seat -> should be ignored + toast
  await availableSeats.nth(10).click();
  await page.waitForTimeout(200);
  log('T2 toast after 11th seat attempt', await page.locator('[data-testid=toast]').textContent().catch(() => 'NO TOAST'));
  log('T2 selected count still (should be unchanged=10)', await page.locator('[data-testid=selected-seats-count]').textContent());

  // deselect one, attempt to select a couch (should fail: 9+2=11 > 10)
  await availableSeats.nth(0).click(); // careful: nth(0) might now be unavailable/selected state changed; use a selected seat instead
  await page.waitForTimeout(100);

  const selectedSeatsNow = page.locator('[data-testid=seat][data-state=selected]');
  const selectedCountNow = await selectedSeatsNow.count();
  log('T2 selected seat elements after deselect-attempt', selectedCountNow);

  // try couch when 9 selected (9+2=11 -> blocked)
  const couchAvail = page.locator('[data-testid=couch][data-state=available]').first();
  await couchAvail.click();
  await page.waitForTimeout(200);
  log('T2 toast after couch attempt at 9 selected', await page.locator('[data-testid=toast]').textContent().catch(() => 'NO TOAST'));
  log('T2 selected count after couch-blocked attempt (should be 9)', await page.locator('[data-testid=selected-seats-count]').textContent());

  // deselect all the way down to 0, reselect 1 seat for the rest of flow
  // click every currently-selected seat to clear
  let selLoop = await page.locator('[data-testid=seat][data-state=selected]').all();
  for (const el of selLoop) { await el.click(); await page.waitForTimeout(30); }
  log('T2 selected count after clearing all', await page.locator('[data-testid=selected-seats-count]').textContent());

  await page.locator('[data-testid=seat][data-state=available]').first().click();
  await page.waitForTimeout(100);
  log('T2 selected count after reselecting 1', await page.locator('[data-testid=selected-seats-count]').textContent());

  // ---- Test 3: reload seat-selection mid-selection -> persists ----
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  log('T3 selected count after reload (should still be 1)', await page.locator('[data-testid=selected-seats-count]').textContent());
  log('T3 url after reload', page.url());

  // continue to summary -> checkout
  await page.locator('[data-testid=continue-button]').click();
  await page.waitForURL(/\/summary/);
  await page.waitForTimeout(200);
  await page.locator('[data-testid=confirm-button]').click();
  await page.waitForURL(/\/checkout/);
  await page.waitForTimeout(200);

  // check labels for double-asterisk bug fix
  log('T4 first-name-label text', await page.locator('[data-testid=first-name-label]').textContent());
  log('T4 phone-label text', await page.locator('[data-testid=phone-label]').textContent());

  // fill partial form, reload -> values persist but touched/error state resets
  await page.locator('[data-testid=first-name-input]').fill('Jan');
  await page.locator('[data-testid=last-name-input]').fill('X'); // invalid: too short, but don't blur yet... actually fill + blur both trigger touched via blur event normally
  await page.locator('[data-testid=email-input]').fill('jan@example.com');
  await page.waitForTimeout(100);
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  log('T5 url after checkout reload', page.url());
  log('T5 first-name-input value after reload (should persist=Jan)', await page.locator('[data-testid=first-name-input]').inputValue());
  log('T5 any visible error after reload (should be none - untouched)', await page.locator('.error').count());

  log('ERRORS so far:', JSON.stringify(errors));
  await browser.close();
})();

