const { chromium } = require('playwright-core');

(async () => {
  const browser = await chromium.launch({
    executablePath: '/opt/ms-playwright/chromium-1234/chrome-linux/chrome',
    args: ['--no-sandbox'],
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  const errors = [];
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
  page.on('pageerror', (err) => errors.push('PAGEERROR: ' + err.message));

  await page.addInitScript(() => {
    const FIXED = new Date(2026, 8, 15, 10, 0, 0).getTime();
    const OriginalDate = Date;
    class FakeDate extends OriginalDate {
      constructor(...args) { if (args.length === 0) super(FIXED); else super(...args); }
      static now() { return FIXED; }
    }
    Date = FakeDate;
  });

  const BASE = 'http://[::1]:4200';
  function log(l, v) { console.log(l + ':', v); }

  await page.goto(BASE + '/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  await page.locator('[data-testid=screening-button]').first().click();
  await page.waitForURL(/\/seats/);
  await page.waitForTimeout(200);
  const screeningId = page.url().match(/screenings\/(\d+)\//)[1];

  await page.locator('[data-testid=seat][data-state=available]').first().click();
  await page.locator('[data-testid=continue-button]').click();
  await page.waitForURL(/\/summary/);
  await page.waitForTimeout(200);
  await page.locator('[data-testid=confirm-button]').click();
  await page.waitForURL(/\/checkout/);
  await page.waitForTimeout(200);

  await page.locator('[data-testid=first-name-input]').fill('Jan');
  await page.locator('[data-testid=last-name-input]').fill('Kowalski');
  await page.locator('[data-testid=email-input]').fill('jan@example.com');
  await page.locator('[data-testid=confirm-email-input]').fill('jan@example.com');
  await page.locator('[data-testid=terms-checkbox]').click();
  await page.locator('[data-testid=pay-button]').click();
  await page.waitForURL(/\/confirmation/, { timeout: 8000 });
  await page.waitForTimeout(300);
  log('paid confirmation message', await page.locator('[data-testid=confirmation-message]').textContent());

  // reload confirmation -> should still show confirmation
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  log('url after confirmation reload', page.url());
  log('confirmation message after reload', await page.locator('[data-testid=confirmation-message]').textContent().catch(() => 'MISSING'));

  // accessing checkout/summary for the now-paid screening should redirect (booking.paid = true, guard requires !paid)
  await page.goto(BASE + `/screenings/${screeningId}/summary`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  log('url visiting summary for paid booking (should redirect to /)', page.url());

  // go back to confirmation and click continue
  await page.goto(BASE + '/confirmation', { waitUntil: 'networkidle' }).catch(() => {});
  await page.waitForTimeout(300);
  log('url re-visiting /confirmation after navigating away (booking still paid, should show confirmation)', page.url());
  await page.locator('[data-testid=confirmation-continue-button]').click();
  await page.waitForTimeout(300);
  log('url after clicking Continue (should be /)', page.url());

  // visiting confirmation again after clear -> should redirect to /
  await page.goto(BASE + '/confirmation', { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  log('url visiting /confirmation after booking cleared (should redirect to /)', page.url());

  // start a new booking on same screening -> seat map should show none selected, checkout form empty
  await page.goto(BASE + `/screenings/${screeningId}/seats`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(300);
  log('selected count on fresh visit to same screening (should be 0)', await page.locator('[data-testid=selected-seats-count]').textContent());

  console.log('ERRORS:', JSON.stringify(errors));
  await browser.close();
})();

